// playwright.config.ts
import { defineConfig, devices } from '@playwright/test';

export default defineConfig({
  // Tests run in parallel within a single worker; sharding across workers is via CLI.
  fullyParallel: true,
  workers: process.env.CI ? 4 : '50%',

  // 30 seconds per test; long enough for an e2e, short enough that sleeps stand out.
  timeout: 30_000,
  expect: { timeout: 10_000 },

  // 2 retries in CI catches transient infra noise; 0 locally so flake surfaces.
  retries: process.env.CI ? 2 : 0,

  reporter: [
    ['list'],
    ['html', { open: 'never' }],
    ['json', { outputFile: 'test-results/results.json' }],
  ],

  use: {
    baseURL: process.env.BASE_URL ?? 'http://localhost:3000',
    trace: 'on-first-retry',
    screenshot: 'only-on-failure',
    video: 'retain-on-failure',
    actionTimeout: 10_000,
    navigationTimeout: 15_000,
  },

  projects: [
    { name: 'chromium', use: { ...devices['Desktop Chrome'] } },
    { name: 'mobile-safari', use: { ...devices['iPhone 14'] } },
  ],
});

// In CI, invoke as:
//   npx playwright test --shard=${{ matrix.shard }}/4
// where matrix.shard ∈ {1,2,3,4}.
